(2302298, 317544, 48487, '<td valign="top">Great texture on the twine.  I don''t think the burning adds anything to the picture as a whole and especially not to the texture aspect of it.  6</td>', 'Great texture on the twine.  I don''t think the burning adds anything to the picture as a whole and especially not to the texture aspect of it.  6', '2006-04-10 18:45:44.000000', NULL, 1),
(2302307, 316726, 48487, '<td valign="top">Good shot.  I like how the lighting catches the granules of sugar.  I think the background is very complimentary to the colors of the candies.  The way they are spaced draws me right to the bunch near the goblet and makes me want to reach out and grab some.</td>', 'Good shot.  I like how the lighting catches the granules of sugar.  I think the background is very complimentary to the colors of the candies.  The way they are spaced draws me right to the bunch near the goblet and makes me want to reach out and grab some.', '2006-04-10 18:54:21.000000', NULL, 1),
(2302387, 317719, 39850, '<td valign="top">9 - Very nice.  Lines, composition, color, depth and texture all very good.  The only thing is the white something upper right corner, although likely natural, perhaps cloned out, who knows.  Perhaps a slight variation in angle/slope and lighting may have given this a little extra, not sure.  Perhaps a little more height too, but it might be that I''d just like to see it ''bigger'' - if that makes sense.</td>', '9 - Very nice.  Lines, composition, color, depth and texture all very good.  The only thing is the white something upper right corner, although likely natural, perhaps cloned out, who knows.  Perhaps a slight variation in angle/slope and lighting may have given this a little extra, not sure.  Perhaps a little more height too, but it might be that I''d just like to see it ''bigger'' - if that makes sense.', '2006-04-10 19:49:45.000000', NULL, 1),
(2302390, 317813, 39850, '<td valign="top">7 - Good texture capture and abstract.  Looks like good control of the whites.  A more finely tuned crop make this even better in my opinion.</td>', '7 - Good texture capture and abstract.  Looks like good control of the whites.  A more finely tuned crop make this even better in my opinion.', '2006-04-10 19:52:28.000000', NULL, 1),
(2302393, 315888, 39850, '<td valign="top">7 - Oh, very nice.  Angle, composition and color(s), very nice.  For this Challenge though.. really wish the texture was stronger.</td>', '7 - Oh, very nice.  Angle, composition and color(s), very nice.  For this Challenge though.. really wish the texture was stronger.', '2006-04-10 19:55:24.000000', NULL, 1),
(2302416, 316036, 39850, '<td valign="top">5 - Like the concept and composition, colors are nice.  To me, the strongest textures captured here are the orchid petals and the wall behind the iron - so your title draws attention away from the strongest textures, in my opinion.  A more finely tuned crop would have also made this better in my opinion.  Minor, but the iris is barely discernible at the bottom and looks like it may be in a glass container, but can''t quite make it out.  With all the textures available here, perhaps reducing the focus to just one or two, may have made this a stronger image in my opinion, especially for this Challenge.  The lighting is nice.</td>', '5 - Like the concept and composition, colors are nice.  To me, the strongest textures captured here are the orchid petals and the wall behind the iron - so your title draws attention away from the strongest textures, in my opinion.  A more finely tuned crop would have also made this better in my opinion.  Minor, but the iris is barely discernible at the bottom and looks like it may be in a glass container, but can''t quite make it out.  With all the textures available here, perhaps reducing the focus to just one or two, may have made this a stronger image in my opinion, especially for this Challenge.  The lighting is nice.', '2006-04-10 20:09:53.000000', NULL, 1),
(2302431, 317298, 39850, '<td valign="top">7 - Nice concept and composition.  Perhaps a tweaking of the ''lighting'', the little bit of ''fluff'' removed and a little sharper, make this even better in my opinion.</td>', '7 - Nice concept and composition.  Perhaps a tweaking of the ''lighting'', the little bit of ''fluff'' removed and a little sharper, make this even better in my opinion.', '2006-04-10 20:17:10.000000', NULL, 1),
(2302435, 317524, 39850, '<td valign="top">4 - Good concept.  Gamma/something issues.  Frame detracts at this size in my opinion.  Depending what you had to work with, a variation in composition (more up the top - where the best focus is) may have made this better in my opinion.</td>', '4 - Good concept.  Gamma/something issues.  Frame detracts at this size in my opinion.  Depending what you had to work with, a variation in composition (more up the top - where the best focus is) may have made this better in my opinion.', '2006-04-10 20:20:58.000000', NULL, 1),
(2302443, 316737, 39850, '<td valign="top">8 - Very good.  Although the blue in the background both complements this and helps ''bring it out'', some sort of variation (or elimination perhaps) of it (the blue), make this even better in my opinion, not sure what to suggest though.  Like the angle and the macro.</td>', '8 - Very good.  Although the blue in the background both complements this and helps ''bring it out'', some sort of variation (or elimination perhaps) of it (the blue), make this even better in my opinion, not sure what to suggest though.  Like the angle and the macro.', '2006-04-10 20:25:13.000000', NULL, 1),
(2302447, 317274, 39850, '<td valign="top">8 - Wow.  Although it likely gives it a required context/perspective, a finer cropping, especially bottom right, likely make this even better in my opinion.  Perhaps (depending what is there/you had to work with) a little more width too, not sure, perhaps just a different shot then, if that makes sense.  Sure this looks great wall size and this size doesn''t do the detail you''ve captured justice.</td>', '8 - Wow.  Although it likely gives it a required context/perspective, a finer cropping, especially bottom right, likely make this even better in my opinion.  Perhaps (depending what is there/you had to work with) a little more width too, not sure, perhaps just a different shot then, if that makes sense.  Sure this looks great wall size and this size doesn''t do the detail you''ve captured justice.', '2006-04-10 20:31:02.000000', NULL, 1),
(2302461, 315885, 39850, '<td valign="top">8 - Nice texture capture and shot.  Depending, of course, what you had to work with, quality and frame wise, more included and taking advantage of the 720 pixel allowance likely made this even better in my opinion.  A more finely tuned crop at the top also.  The beginning of the reflection looks like good potential, but perhaps more apt for another shot/Challenge.  Not sure on the frame, but minor.</td>', '8 - Nice texture capture and shot.  Depending, of course, what you had to work with, quality and frame wise, more included and taking advantage of the 720 pixel allowance likely made this even better in my opinion.  A more finely tuned crop at the top also.  The beginning of the reflection looks like good potential, but perhaps more apt for another shot/Challenge.  Not sure on the frame, but minor.', '2006-04-10 20:43:33.000000', NULL, 1),
(2302464, 317125, 39850, '<td valign="top">8 - Nice colors and composition.  More detail/texture discernible in the wood make this even better in my opinion, especially for this Challenge.  Perhaps a little more at the top included (if you had it of course), but not sure, ''works'' as is.</td>', '8 - Nice colors and composition.  More detail/texture discernible in the wood make this even better in my opinion, especially for this Challenge.  Perhaps a little more at the top included (if you had it of course), but not sure, ''works'' as is.', '2006-04-10 20:47:45.000000', NULL, 1),
(2302489, 315104, 30605, '<td valign="top">Returning for comment. At first, I gave this photo a low score since background has a weird feel to it. But looking at it again, I realized I was too hard. The background has a little something hard to tell. A bit distracting though. bumping to 6.</td>', 'Returning for comment. At first, I gave this photo a low score since background has a weird feel to it. But looking at it again, I realized I was too hard. The background has a little something hard to tell. A bit distracting though. bumping to 6.', '2006-04-10 21:02:41.000000', NULL, 1),
(2302509, 315109, 30605, '<td valign="top">Composition is not too exciting. A bit too much dead space above the rose. And you camera really needs some cleaning; you got dust bunny all over the place. You should have clone them out in post processing. There are a bit too obvious in this plain background.</td>', 'Composition is not too exciting. A bit too much dead space above the rose. And you camera really needs some cleaning; you got dust bunny all over the place. You should have clone them out in post processing. There are a bit too obvious in this plain background.', '2006-04-10 21:17:41.000000', NULL, 1),
(2302574, 316685, 39850, '<td valign="top">8 - Very nice.  Good vivid coloring and the texture capture and detail is good.  Difficult, but perhaps the focal point(s) adjusted slightly, don''t know how, just like to see those ''bristles'' more defined.  Not sure what this is, will be back PC to see.  The only two things in my opinion which detract from this shot, but both fairly minor, are the slightly ''blown'' area middle left and the line/curve of the petal/frond/whatever bottom left.  Also fairly minor but a more finely tuned cropped may have also made this even better, in my opinion.  Nice title.</td>', '8 - Very nice.  Good vivid coloring and the texture capture and detail is good.  Difficult, but perhaps the focal point(s) adjusted slightly, don''t know how, just like to see those ''bristles'' more defined.  Not sure what this is, will be back PC to see.  The only two things in my opinion which detract from this shot, but both fairly minor, are the slightly ''blown'' area middle left and the line/curve of the petal/frond/whatever bottom left.  Also fairly minor but a more finely tuned cropped may have also made this even better, in my opinion.  Nice title.', '2006-04-10 22:03:18.000000', NULL, 1),
(2302581, 317301, 173, '<td valign="top">The title really makes this one! Great job on the photo too. High marks.</td>', 'The title really makes this one! Great job on the photo too. High marks.', '2006-04-10 22:05:42.000000', NULL, 1),
(2302585, 315730, 39850, '<td valign="top">6 - Nice.  Good concept.  Colors are good.  Different angle perhaps, the OOF area dominates this too much within the composition in my opinion.  Like the detail and clarity on the other areas though.  Not sure on the frame.</td>', '6 - Nice.  Good concept.  Colors are good.  Different angle perhaps, the OOF area dominates this too much within the composition in my opinion.  Like the detail and clarity on the other areas though.  Not sure on the frame.', '2006-04-10 22:07:09.000000', NULL, 1),
(2302596, 315088, 3102, '<td valign="top">Damn, that turned out great!</td>', 'Damn, that turned out great!', '2006-04-10 22:11:25.000000', NULL, 1),
(2302600, 317603, 39850, '<td valign="top">6 - Very good concept.  Difficult shot, I know.  The detail and texture on/in the areas that are in focus is very good, unfortunately the OOF areas dominate more, in my opinion.  A slight tweaking of the colors, perhaps a nudge rotation up on the right (for added symmetry and balance) and a more finely tuned crop, especially on the left, likely have helped this in my opinion, however you''d still be left with the fact that the two fronds are ''in the way'', so perhaps a different angle, who knows.</td>', '6 - Very good concept.  Difficult shot, I know.  The detail and texture on/in the areas that are in focus is very good, unfortunately the OOF areas dominate more, in my opinion.  A slight tweaking of the colors, perhaps a nudge rotation up on the right (for added symmetry and balance) and a more finely tuned crop, especially on the left, likely have helped this in my opinion, however you''d still be left with the fact that the two fronds are ''in the way'', so perhaps a different angle, who knows.', '2006-04-10 22:12:22.000000', NULL, 1),
(2302614, 317190, 327, '<td valign="top">Really nice-like the intense look.</td>', 'Really nice-like the intense look.', '2006-04-10 22:22:15.000000', NULL, 1),
(2302616, 317015, 39850, '<td valign="top">7 - Like this.  Tweaking of the colors/''lighting'', whilst difficult I realize with the whites, may have made this even better in my opinion.  Not sure on the frame color, perhaps a color from within the shot may have complemented and lifted the shot more.  Texture detail middle-down, is good, ''if only'' to have that detail in more of the shot, also make this even better in my opinion, especially for this Challenge.</td>', '7 - Like this.  Tweaking of the colors/''lighting'', whilst difficult I realize with the whites, may have made this even better in my opinion.  Not sure on the frame color, perhaps a color from within the shot may have complemented and lifted the shot more.  Texture detail middle-down, is good, ''if only'' to have that detail in more of the shot, also make this even better in my opinion, especially for this Challenge.', '2006-04-10 22:23:00.000000', NULL, 1),
(2302639, 317825, 509, '<td valign="top">I like the subject, but the presentation seems a bit lacking.  Maybe a little more depth of field on the bark would help, but as it is, there isn''t a lot to focus on here.</td>', 'I like the subject, but the presentation seems a bit lacking.  Maybe a little more depth of field on the bark would help, but as it is, there isn''t a lot to focus on here.', '2006-04-10 22:41:19.000000', NULL, 1),
(2302640, 317613, 509, '<td valign="top">I like the cabbage, but why the carrot?  I''d prefer this cropped just above the carrot - the water droplets and the makeup of the cabbage leaves are the real focal points here.</td>', 'I like the cabbage, but why the carrot?  I''d prefer this cropped just above the carrot - the water droplets and the makeup of the cabbage leaves are the real focal points here.', '2006-04-10 22:43:00.000000', NULL, 1),
(2302643, 317265, 509, '<td valign="top">Perfect backlighting!  Really great shot.</td>', 'Perfect backlighting!  Really great shot.', '2006-04-10 22:44:35.000000', NULL, 1),
(2302650, 317815, 509, '<td valign="top">Good subject - a little dodging and burning might add some contrast to the shot.</td>', 'Good subject - a little dodging and burning might add some contrast to the shot.', '2006-04-10 22:45:23.000000', NULL, 1),
(2302655, 317275, 509, '<td valign="top">Good subject and execution.  I''d suggest cropping tighter on top - I think the eyes should be the point of impact here, but the extra space on the forehead distracts from that slightly.</td>', 'Good subject and execution.  I''d suggest cropping tighter on top - I think the eyes should be the point of impact here, but the extra space on the forehead distracts from that slightly.', '2006-04-10 22:46:42.000000', NULL, 1),
(2302661, 317274, 509, '<td valign="top">I like the effect on the sky (the transition to darkness).  Interesting subject and nice execution.</td>', 'I like the effect on the sky (the transition to darkness).  Interesting subject and nice execution.', '2006-04-10 22:48:20.000000', NULL, 1),
(2302662, 315833, 509, '<td valign="top">Awesome shot, wouldn''t be surprised to see this ribbon.</td>', 'Awesome shot, wouldn''t be surprised to see this ribbon.', '2006-04-10 22:48:40.000000', NULL, 1),
(2302671, 316938, 509, '<td valign="top">Is that the block of a viper?  The emphasis on the textures is there, but could be stronger.</td>', 'Is that the block of a viper?  The emphasis on the textures is there, but could be stronger.', '2006-04-10 22:52:21.000000', NULL, 1),
(2302674, 317287, 509, '<td valign="top">I like the framing and colors.  A smaller aperture might add some sharpness to the edges of the lizard.</td>', 'I like the framing and colors.  A smaller aperture might add some sharpness to the edges of the lizard.', '2006-04-10 22:54:22.000000', NULL, 1),
(2302705, 317797, 38032, '<td valign="top">perfect focus and i like the complimentary background and he looks like a really nice dragon :) 8</td>', 'perfect focus and i like the complimentary background and he looks like a really nice dragon :) 8', '2006-04-10 23:09:18.000000', NULL, 1),
(2302709, 317487, 38032, '<td valign="top">great backlighting here.</td>', 'great backlighting here.', '2006-04-10 23:10:41.000000', NULL, 1),
(2302711, 314525, 38032, '<td valign="top">like it - simple yet texturiffic</td>', 'like it - simple yet texturiffic', '2006-04-10 23:11:01.000000', NULL, 1),
(2302717, 317321, 38032, '<td valign="top">thaz craazzaaahhh!!!. . ... this guy must be frozen or dead .... I think this is one of the most detailed macro-flies I''ve seen ... really nice and educational too !  9</td>', 'thaz craazzaaahhh!!!. . ... this guy must be frozen or dead .... I think this is one of the most detailed macro-flies I''ve seen ... really nice and educational too !  9', '2006-04-10 23:12:30.000000', NULL, 1),
(2302721, 317637, 38032, '<td valign="top">DOF is great here - the floating pollen knobs (pestals?? - drawing a botany blank here) are vexing to the eye..  7</td>', 'DOF is great here - the floating pollen knobs (pestals?? - drawing a botany blank here) are vexing to the eye..  7', '2006-04-10 23:14:10.000000', NULL, 1),
(2302726, 317496, 38032, '<td valign="top">kinda fools the eye - neat texture though but the DOF is confusing which I think weakens it a tad.  i might try burning the distant areas to separate them a little ... wait ... they''re already burnt! Very nice though.</td>', 'kinda fools the eye - neat texture though but the DOF is confusing which I think weakens it a tad.  i might try burning the distant areas to separate them a little ... wait ... they''re already burnt! Very nice though.', '2006-04-10 23:15:52.000000', NULL, 1),
(2302727, 317495, 38032, '<td valign="top">Iceland, no doubt.  Spectacular wide!</td>', 'Iceland, no doubt.  Spectacular wide!', '2006-04-10 23:16:26.000000', NULL, 1),
(2302768, 317815, 43031, '<td valign="top">I still get flashbacks to the branch challenge every time I see one of these, I voted on every one of those dammned looking up a tree pictures.</td>', 'I still get flashbacks to the branch challenge every time I see one of these, I voted on every one of those dammned looking up a tree pictures.', '2006-04-10 23:47:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2302850, 317773, 39057, '<td valign="top">This is a really good and dare-ing shot. It is almost too good for tyhe textures challenge. Although I see texture in the blanket and the paw, some will be confused as to what your "subject" was.<br/> <br/>7 and I''ll take a 2nd look.</td>', 'This is a really good and dare-ing shot. It is almost too good for tyhe textures challenge. Although I see texture in the blanket and the paw, some will be confused as to what your "subject" was. 7 and I''ll take a 2nd look.', '2006-04-11 00:38:38.000000', NULL, 1),
