(2304452, 317125, 53320, '<td valign="top">BEAUTIFUL</td>', 'BEAUTIFUL', '2006-04-11 20:15:04.000000', NULL, 1),
(2304514, 317682, 33352, '<td valign="top">Brilliant selection for this challenge,the colors work well together,and the different textures show through....10</td>', 'Brilliant selection for this challenge,the colors work well together,and the different textures show through....10', '2006-04-11 20:38:23.000000', NULL, 1),
(2304563, 314444, 30605, '<td valign="top">Cool pattern. Looks like the wave pattern on the backside of Omega''s Seamaster.</td>', 'Cool pattern. Looks like the wave pattern on the backside of Omega''s Seamaster.', '2006-04-11 21:04:49.000000', NULL, 1),
(2304592, 317487, 30605, '<td valign="top">Cool backlight effect. Nice colors.<br/>I could be wrong, but I sense oversharpening in here. The noise pattern in the out of focus area looks exagerated by the sharpening. Sharpening should be used in moderation in my opinion. <br/>I think it''s a side offect of DPC where super sharp photos wins more ofthen than soft photos. So it''s hard to resist when comes time to apply sharpening to our photos. I understand that.</td>', 'Cool backlight effect. Nice colors.I could be wrong, but I sense oversharpening in here. The noise pattern in the out of focus area looks exagerated by the sharpening. Sharpening should be used in moderation in my opinion. I think it''s a side offect of DPC where super sharp photos wins more ofthen than soft photos. So it''s hard to resist when comes time to apply sharpening to our photos. I understand that.', '2006-04-11 21:15:20.000000', NULL, 1),
(2304596, 316354, 30605, '<td valign="top">That a nice composition. Nice "framing". Very artistic. Bumping up.</td>', 'That a nice composition. Nice "framing". Very artistic. Bumping up.', '2006-04-11 21:18:17.000000', NULL, 1),
(2304598, 317751, 75713, '<td valign="top">like the abstract quality... good job</td>', 'like the abstract quality... good job', '2006-04-11 21:20:31.000000', NULL, 1),
(2304599, 317075, 30605, '<td valign="top">Good composition on a rather unexciting subject.</td>', 'Good composition on a rather unexciting subject.', '2006-04-11 21:20:35.000000', NULL, 1),
(2304600, 316417, 32997, '<td valign="top">effective use of light..</td>', 'effective use of light..', '2006-04-11 21:21:45.000000', NULL, 1),
(2304601, 317348, 32997, '<td valign="top">dof really adds to the appeal here..nice work..</td>', 'dof really adds to the appeal here..nice work..', '2006-04-11 21:22:28.000000', NULL, 1),
