(2635174, 317628, 54540, '<td valign="top">I really like the way the insert apppears "over" the string.  The voters just didn''t know what they were looking at or doing for that matter!</td>', 'I really like the way the insert apppears "over" the string.  The voters just didn''t know what they were looking at or doing for that matter!', '2006-07-19 01:44:36.000000', NULL, 0),
(2666279, 317794, 48890, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by jfwolpert:</b></div><hr/><i> too small and kind of flat lighting </i></td></tr></table> <br/>Gotta love this: flat lighting.  Yeah, right! :)<br/> <br/>Anyways, I like the square crop colour version better, I think.  This is still a nice picture, though.  The crop form factor is maybe a bit too weird, I am not sure what it does for me.  Why did you crop it like that?</td>', 'Originally posted by jfwolpert: too small and kind of flat lighting  Gotta love this: flat lighting.  Yeah, right! :) Anyways, I like the square crop colour version better, I think.  This is still a nice picture, though.  The crop form factor is maybe a bit too weird, I am not sure what it does for me.  Why did you crop it like that?', '2006-07-27 00:44:53.000000', NULL, 0),
(2666639, 317321, 62812, '<td valign="top">That is amazing - the detail is quite astonishing!</td>', 'That is amazing - the detail is quite astonishing!', '2006-07-27 02:58:54.000000', NULL, 0),
(2667221, 317794, 50695, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by agenkin:</b></div><hr/><i>Anyways, I like the square crop colour version better, I think.  This is still a nice picture, though.  The crop form factor is maybe a bit too weird, I am not sure what it does for me.  Why did you crop it like that? </i></td></tr></table> <br/> <br/>I like the square crop better, too, but I thought this met the texture challenge better. That is why it''s such a severe crop. I cropped out the surface details/highlights so that nothing would "pop". A surefire formula for a low score! <br/> <br/>I think most dpc voters were interpreting texture differently than I was. They wanted a picture of something that they could imagine touching. I was trying to create a "visual texture." In other words, a consistent pattern across the entire field of the picture. No subject, just "surface."</td>', 'Originally posted by agenkin:Anyways, I like the square crop colour version better, I think.  This is still a nice picture, though.  The crop form factor is maybe a bit too weird, I am not sure what it does for me.  Why did you crop it like that?   I like the square crop better, too, but I thought this met the texture challenge better. That is why it''s such a severe crop. I cropped out the surface details/highlights so that nothing would "pop". A surefire formula for a low score!  I think most dpc voters were interpreting texture differently than I was. They wanted a picture of something that they could imagine touching. I was trying to create a "visual texture." In other words, a consistent pattern across the entire field of the picture. No subject, just "surface."', '2006-07-27 10:27:53.000000', NULL, 0),
(2667324, 317794, 48890, '<td valign="top">Well, this is texture to me.  Perhaps the texture alone in a picture is not enough...</td>', 'Well, this is texture to me.  Perhaps the texture alone in a picture is not enough...', '2006-07-27 11:08:05.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2672128, 314892, 52336, '<td valign="top">Nice portrait overall, lovely lighting, and great deep contrast, something I''m especially fond of.  There''s a hint of her environment behind her (despite her grandson''s big head in the reflection ;) ), but it''s understated and subtle and just enough to leave us with an impression.  That''s really well done.  Technically, I think this is a superior image.  My only criticism is of the way you''ve composed her.  There''s too much between the chin and top of the head (which is just slightly cut off), and not enough lower down.  I think you could have achieved the subtle environmental effect with a portrait orientation, and thus included more of her.  So much of her face like this really gives it an unsettling disembodied feeling that detracts slightly.  But, as I''ve said, a technically wonderful shot, well executed otherwise.  Nice job.</td>', 'Nice portrait overall, lovely lighting, and great deep contrast, something I''m especially fond of.  There''s a hint of her environment behind her (despite her grandson''s big head in the reflection ;) ), but it''s understated and subtle and just enough to leave us with an impression.  That''s really well done.  Technically, I think this is a superior image.  My only criticism is of the way you''ve composed her.  There''s too much between the chin and top of the head (which is just slightly cut off), and not enough lower down.  I think you could have achieved the subtle environmental effect with a portrait orientation, and thus included more of her.  So much of her face like this really gives it an unsettling disembodied feeling that detracts slightly.  But, as I''ve said, a technically wonderful shot, well executed otherwise.  Nice job.', '2006-07-28 18:07:42.000000', NULL, 0),
(2674261, 315417, 16241, '<td valign="top">nice!</td>', 'nice!', '2006-07-29 16:02:54.000000', NULL, 0),
(2683567, 315373, 16241, '<td valign="top">i like this a lot!</td>', 'i like this a lot!', '2006-08-01 12:37:48.000000', NULL, 0),
